// Run: node --test tests/   (needs dev-data/, generated by tools/build_sheets.py)
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { normalizeLibrary, propose, sessions, nextDay, eligible, dayOf, prescribe, planSeconds, itemSeconds } from '../app/js/planner.js';
import { loadOptions } from '../app/js/weights.js';

const raw = JSON.parse(readFileSync(new URL('../dev-data/library.json', import.meta.url)));
const hist = JSON.parse(readFileSync(new URL('../dev-data/history.json', import.meta.url)));
const lib = normalizeLibrary(raw);
const now = Math.max(...hist.recent.map(r => r[0])) + 864e5;

test('home dumbbell loads come from 2.5 kg handles and 4x1, 4x2, 4x4 kg plates', () => {
  assert.deepEqual(loadOptions(lib, 'Home', 'Dumbbell', 2), [2.5, 4.5, 6.5, 8.5, 10.5, 12.5, 14.5, 16.5]);
  const single = loadOptions(lib, 'Home', 'Dumbbell', 1);
  assert.equal(single[0], 2.5);
  assert.equal(single.at(-1), 30.5);
});

test('home only offers exercises with mat, dumbbells or bodyweight', () => {
  const ok = new Set(['Bodyweight', 'Mat', 'Dumbbell']);
  const home = eligible(lib, 'Home');
  assert.ok(home.length > 40, 'enough home exercises: ' + home.length);
  for (const e of home) assert.ok(e.equipment.every(x => ok.has(x)), e.name + ' ' + e.equipment);
});

test('PPL rotation continues from the last strength session', () => {
  const sess = sessions(lib, hist);
  const order = ['Push', 'Pull', 'Legs'];
  const last = sess.find(s => order.includes(s.day));
  assert.equal(nextDay(lib, sess), order[(order.indexOf(last.day) + 1) % 3]);
});

for (const [day, location, minutes] of [['Push', 'Gym', 60], ['Pull', 'Gym', 45], ['Legs', 'Home', 30], ['Push', 'Home', 75], ['Full Body', 'Gym', 90], ['Legs', 'Gym', 15]]) {
  test(`proposal ${day} @ ${location} ${minutes} min fits the time and ends with core`, () => {
    const p = propose(lib, hist, { day, location, minutes, seed: 42, now });
    const names = p.items.map(i => i.name);
    assert.equal(new Set(names).size, names.length, 'no duplicates');
    const last = lib.byName.get(names.at(-1));
    assert.equal(dayOf(lib, last), 'Core', 'ends with a core exercise: ' + names.at(-1));
    const main = p.items.filter(i => dayOf(lib, lib.byName.get(i.name)) !== 'Core');
    assert.ok(main.length >= 1);
    const muscles = day === 'Full Body' ? ['Push', 'Pull', 'Legs'] : [day];
    for (const i of main) assert.ok(muscles.includes(dayOf(lib, lib.byName.get(i.name))), i.name + ' belongs to ' + day);
    const eligibleNames = new Set(eligible(lib, location).map(e => e.name));
    for (const n of names) assert.ok(eligibleNames.has(n), n + ' possible at ' + location);
    if (minutes >= 30) assert.ok(p.seconds <= minutes * 60 + 120, `time ${Math.round(p.seconds / 60)} <= ${minutes}`);
    if (minutes >= 45) assert.ok(p.seconds >= minutes * 60 * 0.7, `time ${Math.round(p.seconds / 60)} uses budget ${minutes}`);
    console.log(`${day}/${location}/${minutes}: ${Math.round(p.seconds / 60)} min —`, p.items.map(i => `${i.name} ${i.sets.length}x${i.sets[0].reps}@${i.sets[0].weight ?? '?'}`).join(' | '));
  });
}

test('more minutes never gives fewer exercises (same seed)', () => {
  let prev = 0;
  for (const m of [30, 45, 60, 75, 90]) {
    const n = propose(lib, hist, { day: 'Pull', location: 'Gym', minutes: m, seed: 7, now }).items.length;
    assert.ok(n >= prev, `${m} min: ${n} >= ${prev}`);
    prev = n;
  }
});

test('weights in proposals are available at the location', () => {
  for (const location of ['Gym', 'Home']) {
    for (const day of ['Push', 'Pull', 'Legs']) {
      const p = propose(lib, hist, { day, location, minutes: 90, seed: 3, now });
      for (const it of p.items) {
        const e = lib.byName.get(it.name);
        const opts = loadOptions(lib, location, e.load, e.implements);
        for (const s of it.sets) if (opts && s.weight != null && e.type === 'Weighted') assert.ok(opts.includes(s.weight), `${it.name} ${s.weight} at ${location}`);
      }
    }
  }
});

test('progression: all sets at top of range -> heavier weight', () => {
  const e = { ...lib.byName.get('Lat Pulldown'), repMin: 8, repMax: 12, sets: 3 };
  const h = { exercises: { 'Lat Pulldown': { n: 10, last: 1, sets: [[12, 40, 0, 0, 0], [12, 40, 0, 0, 0], [12, 40, 0, 0, 0]] } } };
  const p = prescribe(lib, h, e, 'Gym');
  assert.ok(p.sets[0].weight > 40);
  assert.equal(p.sets[0].reps, 8);
  const h2 = { exercises: { 'Lat Pulldown': { n: 10, last: 1, sets: [[10, 40, 0, 0, 0], [9, 40, 0, 0, 0]] } } };
  const p2 = prescribe(lib, h2, e, 'Gym');
  assert.equal(p2.sets[0].weight, 40);
  assert.equal(p2.sets[0].reps, 10);
});
